compile.workshop:
variables {
    global:
        0: value
}

rule ("issue 47 switch multiple break") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(6, 0, 2, 5), Add(1, Index Of Array Value(Array(1, 2, 3), Global.value))));
            Set Global Variable(value, 1);
        Else;
            If(True);
                Set Global Variable(value, 2);
            Else;
                Set Global Variable(value, 3);
                Set Global Variable(value, 4);
            End;
    }
}
